use strict; use warnings;
my $BIN="/workspace/dataset/test15_executable";
sub esc { my $s=shift; my $o=""; for my $c (split //, $s){ my $v=ord($c);
  if($v==10){$o.="\\n"} elsif($v==13){$o.="\\r"} elsif($v==9){$o.="\\t"}
  elsif($v<32||$v==127){$o.=sprintf("\\x%02X",$v)} elsif($v>127){$o.=sprintf("\\x%02X",$v)}
  else {$o.=$c} } return $o; }
sub run {
  my ($label,@a)=@_;
  die "need 6" unless @a==6;
  my $pid=open(my $fh, "-|");
  if($pid==0){ open(STDERR,">","/tmp/perr") or die; exec($BIN,@a) or exit 127; }
  local $/; my $out=<$fh>; $out="" unless defined $out; close($fh); my $rc=$?>>8;
  my $err=""; if(open(my $e,"<","/tmp/perr")){local $/; $err=<$e>; $err="" unless defined $err;}
  printf("### %s\n", $label);
  printf("    argv = [%s]|[%s]|[%s]|[%s]|[%s]|[%s]\n", map {esc($_)} @a);
  my @L=split(/\n/,$out,-1); pop @L if @L && $L[-1] eq "";
  printf("    exit=%d physlines=%d\n",$rc,scalar(@L));
  for my $i (0..$#L){ printf("   %2d: [%s]<END>\n",$i+1,esc($L[$i])); }
  printf("    STDERR: [%s]\n", esc($err)) if length($err);
  return @L;
}
