// ===================== PATH-TRANSFORM: DEFINITIVE SPEC =====================
// Established by 300+ black-box runs of /workspace/dataset/test15_executable.
// argv: [1]=scheme [2]=host [3]=port [4]=path [5]=query [6]=fragment
// Byte-oriented throughout. No UTF-8 awareness, no locale, no encoding tables.

// ---------- STEP 0: PRECONDITION (happens BEFORE any path work) ----------
// The program parses the port with std::stoi(argv[3]) first. If that throws,
// the process dies by SIGABRT and prints NOTHING (0 lines of stdout).
//   ("http","h","abc","/p","","") -> wait status 134, signal 6, core dumped,
//        stdout = "" , stderr = "terminate called after throwing an instance
//                                of 'std::invalid_argument'\n  what():  stoi\n"
//   ("http","h","",   "/p","","") -> identical abort.
// Then: port_stored = (0 <= n && n <= 65535) ? n : -1.
//   Observed: 65535 -> 65535 ; 65536, 99999, -5, 2147483647, -2147483648 -> -1.

// ---------- STEP 1: THE ONLY PATH TRANSFORM ----------
fn store_path(p: &[u8]) -> Vec<u8> {
    if p.is_empty() { return vec![]; }          // empty stays EXACTLY empty
    if p[0] == b'/' /* 0x2F */ { return p.to_vec(); }  // already rooted: identity
    let mut out = vec![b'/'];                   // otherwise prepend exactly one '/'
    out.extend_from_slice(p);
    out
}
// That is the WHOLE transform. Explicitly NOT done, each verified:
//   * no default of "" to "/"            ("http","example.com","80","","","") -> path()="" , to_string="http://example.com:80"
//   * no dot-segment resolution          "/a/./../b/../../c/" -> "/a/./../b/../../c/" ; "/../../.." -> "/../../.." ; ".." -> "/.."
//   * no duplicate-slash collapsing      100 slashes -> 100 slashes ; "//a//b//" -> "//a//b//"
//   * no trailing-slash add or remove    "/foo" -> "/foo" ; "/foo/" -> "/foo/"
//   * no whitespace trim                 " " -> "/ " ; "  " -> "/  " ; "/a " -> "/a "
//   * no percent-decode (not even before the first-byte test!)
//                                        "%2Fa" -> "/%2Fa"   (5 bytes; a decode-first impl would give "/a" and skip the prefix)
//   * no percent-encode                  "/a b" -> "/a b" ; "/a\x7Fb" -> "/a\x7Fb" ; "/a\xFFb" -> "/a\xFFb"
//   * no '+' <-> ' ' translation         "/a+b" -> "/a+b"
//   * no case folding                    "/ABC/DeF" -> "/ABC/DeF"  (only scheme is lowercased: "HTTP" -> "http")
//   * no re-parsing of '?' or '#'        "/a?b#c" -> path()="/a?b#c", query()="" , fragment()=""
//                                        even when query/fragment are also given:
//                                        ("http","h","80","/a?b","q","f") -> "http://h:80/a?b?q#f"
//   * no scheme/host/port sensitivity    identical result for every scheme incl. "", "mailto", "file", "data",
//                                        "javascript", "urn", "tel", " ", "1", "://", "\xFF", 200x'z'
//   * no length cap                      131000-byte path stored verbatim; 131000-byte relative path -> 131001 bytes
//
// PREDICATE PRECISION (exhaustive first-byte sweep 0x01..0xFF):
//   every byte except 0x2F triggers the prepend, including 0x09 TAB, 0x0A LF,
//   0x0D CR, 0x20 SPACE, 0x2E '.', 0x2B '+', 0x2D '-', 0x30 '0', 0x3A ':',
//   0x3F '?', 0x23 '#', 0x5C '\', 0x7F DEL, and 0x80..0xFF.
//   Byte 0x00 is unreachable: execve truncates argv at NUL.
//     "/a\0b" -> path()="/a" ; "\0abc" -> path()="" (empty!), to_string="http://h:80", is_valid=1.

// ---------- STEP 2: to_string() ----------
fn to_string(scheme:&str, host:&str, port:i32, path:&[u8], query:&str, fragment:&str) -> Vec<u8> {
    let mut s = Vec::new();
    if !scheme.is_empty() {                 // empty scheme drops host AND port too
        s.extend(scheme.as_bytes());        // scheme is already lowercased
        s.extend(b"://");                   // ALWAYS "://", even if host is empty
        s.extend(host.as_bytes());          // host spliced verbatim, no fixups
        if port >= 0 { s.push(b':'); s.extend(port.to_string().as_bytes()); }  // 0 IS printed
    }
    s.extend(path);                         // stored path spliced verbatim, NO separator,
                                            // and NO '/' synthesized when path is empty
    if !query.is_empty()    { s.push(b'?'); s.extend(query.as_bytes()); }
    if !fragment.is_empty() { s.push(b'#'); s.extend(fragment.as_bytes()); }
    s
}
// Exact literal outputs for the surprising cases (all observed):
//   ("http","example.com","80","","q=1","frag") -> "http://example.com:80?q=1#frag"   // authority then '?', no '/'
//   ("http","example.com","80","","","frag")    -> "http://example.com:80#frag"
//   ("http","h","80","","/x","")                -> "http://h:80?/x"
//   ("http","","-1","foo","","")                -> "http:///foo"                      // THREE slashes
//   ("http","","-1","//foo","","")              -> "http:////foo"                     // FOUR slashes
//   ("http","","80","/p","","")                 -> "http://:80/p"
//   ("mailto","","-1","user@example.com","","") -> "mailto:///user@example.com"
//   ("http","h","80","?","q","f")               -> "http://h:80/??q#f"                // two '?'
//   ("http","h","80","#","q","f")               -> "http://h:80/#?q#f"
//   ("http","h/","80","/a","","")               -> "http://h/:80/a"                   // no join cleanup
//   ("","example.com","80","/foo","","")        -> "/foo"                             // host+port vanish
//   ("","example.com","80","","q=1","frag")     -> "?q=1#frag"
//   ("","","-1","//foo","","")                  -> "//foo"
//   ("","example.com","80","","","")            -> ""                                 // empty, yet is_valid=1
//   ("http","","-1","","","")                   -> "http://"                          // non-empty, yet is_valid=0

// ---------- STEP 3: is_valid() ----------
fn is_valid(host:&str, stored_path:&[u8]) -> bool { !host.is_empty() || !stored_path.is_empty() }
// Full truth table observed; scheme/port/query/fragment contribute NOTHING:
//   (host="", path="")   -> 0    ("http","","-1","","q=1","f") -> "http://?q=1#f", is_valid=0
//   (host="", path!="")  -> 1    ("","","-1","a","","")        -> path="/a", to_string="/a", is_valid=1
//   (host!="",path="")   -> 1    ("http","..","-1","","","")   -> "http://..",     is_valid=1
//   (host!="",path!="")  -> 1
// Junk/whitespace hosts count as non-empty: " ", "\t", "0", "..", "%00" -> is_valid=1 with empty path.
// It is NOT derived from to_string(): "http://" is non-empty but invalid, while "" (empty scheme + host
// "example.com" + empty path) is empty but valid.
// Since a non-empty input path can never store as empty, the path term may be tested on either value.

// ---------- STEP 4: PRINTING ----------
// Print, each followed by '\n': scheme, host, port (as decimal i32, "-1" possible),
// stored_path, query, fragment, to_string(), is_valid() as "1"/"0".
// All bytes are written raw, so a path containing LF yields MORE than 8 physical lines:
//   ("http","h","80","a\nb","","") -> 10 physical lines:
//      1 "http"  2 "h"  3 "80"  4 "/a"  5 "b"  6 ""  7 ""  8 "http://h:80/a"  9 "b"  10 "1"
//   ("http","h","80","\n\n","","") -> 12 physical lines (4="/", 5="", 6="").
// With a parseable port, exit status is always 0 and stderr always empty, for every
// path byte sequence tested (control bytes, 0xFF, invalid UTF-8, bad escapes, 131000 bytes).
// Output is deterministic: identical argv reproduced byte-identical stdout across repeats.
